import hashlib
import itertools
import string
import time

def brute_force_hash_crack(hash_to_crack, max_length=8, charset=string.ascii_lowercase + string.digits):
    """
    Attempts to crack a hash using brute-force method.
    """
    for length in range(1, max_length + 1):
        for attempt in itertools.product(charset, repeat=length):
            attempt_str = ''.join(attempt)
            if hashlib.md5(attempt_str.encode()).hexdigest() == hash_to_crack:
                return attempt_str
    return None

def dictionary_attack(hash_to_crack, wordlist_path='common_passwords.txt'):
    """
    Attempts to crack a hash using a dictionary attack.
    """
    try:
        with open(wordlist_path, 'r') as file:
            for line in file:
                password = line.strip()
                if hashlib.md5(password.encode()).hexdigest() == hash_to_crack:
                    return password
    except FileNotFoundError:
        print(f"Wordlist file {wordlist_path} not found.")
    return None

def main():
    print("Password Cracking Tool")
    print("1. Brute Force Attack")
    print("2. Dictionary Attack")
    choice = input("Select attack method (1 or 2): ")

    hash_to_crack = input("Enter the hash to crack: ")

    start_time = time.time()

    if choice == '1':
        print("Starting brute force attack...")
        result = brute_force_hash_crack(hash_to_crack)
    elif choice == '2':
        print("Starting dictionary attack...")
        result = dictionary_attack(hash_to_crack)
    else:
        print("Invalid choice")
        return

    if result:
        print(f"Password found: {result}")
    else:
        print("Password not found in the given parameters.")

